st = lambda p: "***" if p < .01 else "**" if p < .05 else "*" if p < .1 else ""
g = lambda k, v: E[k]["coef"][v]
def cell(v, d=3): return f"{v[0]:.{d}f}{st(v[2])} ({v[1]:.{d}f})"
def b_se(v, d=3): return f"{v[0]:.{d}f} (SE {v[1]:.{d}f})"
def ci95(k, v):
    b, se, _ = g(k, v); t = stats.t.ppf(0.975, E[k]["G"] - 1); return b - t * se, b + t * se
def rep(i, pairs):
    t = B0[i]["text"]
    for a, b in pairs:
        assert t.count(a) == 1, (i, a[:70], t.count(a)); t = t.replace(a, b)
