assert (len(al_keys), n5, n10) == (10, 1, 2), (n5, n10); assert w5 == 0, "a placebo coefficient is significant at 5 percent"
assert all(g(k, v)[2] > .10 for k, v in [("safety", "alder_safe_z"), ("runoff_new", "alder_runoff"), ("runoff_new", "alder_newh"), ("margin_official", "alder_margin_z"), ("align_endorse", "alder_aligned"), ("align_endorse", "alder_opposed")])
assert .05 < g("align_vote", "alder_lf_z")[2] < .10 and g("align_vote", "alder_lf_z")[0] > 0 and g("align_vote_full", "alder_lf_z")[2] > .10
assert g("align_both", "alder_opposed")[2] < .05 and g("align_both", "alder_opposed")[0] < 0 and g("align_both", "alder_aligned")[2] > .10 and E["align_both"]["G"] == 34
assert all(g(k, v)[2] > .10 for k, v in [("safety_full", "alder_safe_z"), ("safety_noappt", "alder_safe_z"), ("align_endorse_full", "alder_aligned"), ("align_endorse_full", "alder_opposed")])
