def rowcells(keys):
    return keys
SAFE, RUN, NEW, MAR, AL, OP, LF = "safe_z", "runoff", "newh", "margin_z", "aligned", "opposed", "lf_z"
colspec = [("safety", [SAFE]), ("runoff_new", [RUN, NEW]), ("margin_official", [MAR]), ("align_endorse", [AL, OP]), ("align_vote", [LF]), ("align_both", [AL, OP, LF])]
labels = [(SAFE, "Seat safety (+1 SD)"), (RUN, "Runoff required"), (NEW, "New office-holder"), (MAR, "Runoff margin (+1 SD)"), (AL, "Endorsed eventual mayor"), (OP, "Endorsed runner-up"), (LF, "Ward vote for mayor (+1 SD)")]
def panel(prefix):
    rows = []
    for var, lab in labels:
        r = [lab]
        for k, vs in colspec: r.append(cell(g(k, f"{prefix}_{var}")) if var in vs else "")
        rows.append(r)
    return rows
